-- Tablas de Finanzia (copiadas del proyecto original de Supabase).
--
-- Es lo primero que se corre en un proyecto nuevo: SQL Editor → New query → Run.
-- Ya están en orden: cada tabla solo usa tablas creadas antes. Si una ya existe, se salta.
--
-- Los id usan GENERATED BY DEFAULT (no ALWAYS) para poder importar datos con sus id desde CSV.
-- Si se importan datos, después hay que correr reajustar_contadores.sql.

create table if not exists public.usuarios (
  id_usuario bigint generated by default as identity not null,
  nombre character varying not null,
  correo character varying not null unique,
  contrasena character varying,
  constraint usuarios_pkey primary key (id_usuario)
);

create table if not exists public.colores (
  id_color bigint generated by default as identity not null,
  color character varying not null,
  constraint colores_pkey primary key (id_color)
);

create table if not exists public.categorias (
  id_categoria bigint generated by default as identity not null,
  id_usuario bigint not null,
  id_color bigint,
  nombre character varying not null,
  tipo character varying not null,
  activo boolean not null default true,
  constraint categorias_pkey primary key (id_categoria),
  constraint categorias_id_usuario_fkey foreign key (id_usuario) references public.usuarios (id_usuario),
  constraint categorias_id_color_fkey foreign key (id_color) references public.colores (id_color)
);

create table if not exists public.cuentas (
  id_cuenta bigint generated by default as identity not null,
  id_usuario bigint not null,
  id_color bigint,
  nombre character varying not null,
  tipo character varying not null,
  saldo_inicial numeric not null default 0,
  fecha_creacion timestamp with time zone not null default now(),
  activo boolean not null default true,
  constraint cuentas_pkey primary key (id_cuenta),
  constraint cuentas_id_usuario_fkey foreign key (id_usuario) references public.usuarios (id_usuario),
  constraint cuentas_id_color_fkey foreign key (id_color) references public.colores (id_color)
);

create table if not exists public.metas (
  id_meta bigint generated by default as identity not null,
  id_usuario bigint not null,
  nombre character varying not null,
  monto_objetivo numeric not null,
  fecha_limite timestamp with time zone,
  fecha_creacion timestamp with time zone not null default now(),
  activo boolean not null default true,
  constraint metas_pkey primary key (id_meta),
  constraint metas_id_usuario_fkey foreign key (id_usuario) references public.usuarios (id_usuario)
);

create table if not exists public.movimientos (
  id_movimiento bigint generated by default as identity not null,
  id_usuario bigint not null,
  id_cuenta bigint not null,
  id_categoria bigint,
  tipo character varying not null,
  monto numeric not null,
  descripcion character varying,
  fecha timestamp with time zone not null default now(),
  activo boolean not null default true,
  constraint movimientos_pkey primary key (id_movimiento),
  constraint movimientos_id_usuario_fkey foreign key (id_usuario) references public.usuarios (id_usuario),
  constraint movimientos_id_cuenta_fkey foreign key (id_cuenta) references public.cuentas (id_cuenta),
  constraint movimientos_id_categoria_fkey foreign key (id_categoria) references public.categorias (id_categoria)
);

create table if not exists public.aportes (
  id_aporte bigint generated by default as identity not null,
  id_meta bigint not null,
  id_cuenta bigint not null,
  monto numeric not null,
  fecha timestamp with time zone not null default now(),
  constraint aportes_pkey primary key (id_aporte),
  constraint aportes_id_cuenta_fkey foreign key (id_cuenta) references public.cuentas (id_cuenta),
  constraint aportes_id_meta_fkey foreign key (id_meta) references public.metas (id_meta)
);

create table if not exists public.conversaciones (
  id_conversacion bigint generated by default as identity not null,
  id_usuario bigint not null,
  fecha_creacion timestamp with time zone not null default now(),
  titulo character varying,
  activo boolean not null default true,
  constraint conversaciones_pkey primary key (id_conversacion),
  constraint conversaciones_id_usuario_fkey foreign key (id_usuario) references public.usuarios (id_usuario)
);

create table if not exists public.mensajes (
  id_mensaje bigint generated by default as identity not null,
  id_conversacion bigint not null,
  rol character varying not null,
  contenido text not null,
  fecha timestamp with time zone not null default now(),
  activo boolean not null default true,
  constraint mensajes_pkey primary key (id_mensaje),
  constraint mensajes_id_conversacion_fkey foreign key (id_conversacion) references public.conversaciones (id_conversacion)
);
